import{_ as e,o as n,c as t,a4 as o}from"./chunks/framework.Fmm5XFPO.js";const f=JSON.parse('{"title":"💼 Experience","description":"","frontmatter":{"lastUpdated":true,"prev":{"text":"← Back to Home","link":"/index"},"next":{"text":"Skills →","link":"/Skills/index"}},"headers":[],"relativePath":"Experience/index.md","filePath":"Experience/index.md","lastUpdated":1788961255000}'),r={name:"Experience/index.md"},a=o('<h1 id="💼-experience" tabindex="-1">💼 Experience <a class="header-anchor" href="#💼-experience" aria-label="Permalink to &quot;💼 Experience&quot;">​</a></h1><hr><h2 id="ai-infrastructure-full-stack-engineer-—-neuralix-ai" tabindex="-1">AI Infrastructure &amp; Full-Stack Engineer — Neuralix.ai <a class="header-anchor" href="#ai-infrastructure-full-stack-engineer-—-neuralix-ai" aria-label="Permalink to &quot;AI Infrastructure &amp; Full-Stack Engineer — Neuralix.ai&quot;">​</a></h2><p><strong>April 2025 – Present</strong> · Delhi, India · On-site</p><div class="info custom-block"><p class="custom-block-title">🛡️ EKAM AI</p><p>An indigenous <strong>Defence AI-as-a-Service</strong> platform, built under the Ministry of Defence <strong>iDEX ADITI 2.0</strong> initiative and launched nationally at the <strong>Chanakya Defence Dialogue 2025</strong>. It runs inside secure air-gapped sites, so every package, model weight and upgrade has to be carried in offline.</p></div><h3 id="what-i-own" tabindex="-1">What I own <a class="header-anchor" href="#what-i-own" aria-label="Permalink to &quot;What I own&quot;">​</a></h3><p><strong>Model serving</strong> Production inference on <strong>vLLM</strong> and <strong>NVIDIA Triton Inference Server</strong> across GPU nodes, serving LLMs, SLMs, VLMs, OCR, embedding and reranking models. Tuning continuous batching, KV-cache sizing and request scheduling so a fixed number of GPUs serves more users at lower latency.</p><p><strong>Model lifecycle</strong> Benchmarking candidate open-source models on latency, cost and task accuracy, validating their outputs, then promoting them from evaluation through staging into production serving.</p><p><strong>Air-gapped delivery</strong> Offline package mirrors, model-weight distribution, dependency resolution, version upgrades and on-site incident support with no external network path. Standalone desktop distributions and VDI deployments for restricted sites.</p><p><strong>Application layer</strong> The platform&#39;s backend in <strong>Python</strong> and <strong>FastAPI</strong>, with <strong>React</strong> interfaces, <strong>PostgreSQL</strong>, <strong>Redis</strong> and <strong>NGINX</strong> behind AI-powered document and retrieval workflows.</p><p><strong>Reliability</strong> Telemetry with <strong>Prometheus</strong> and <strong>Grafana</strong>, profiling application hot paths, then tuning async execution, caching and database access — cutting average API response latency by <strong>40%</strong>.</p><p><strong>GPU coordination</strong> Primary interface between the AI platform team and the GPU hardware and infrastructure teams, running root-cause analysis across application, CUDA driver, network and hardware layers.</p><p><strong>Documentation</strong> The SOPs, runbooks and architecture documents used for on-site deployment, troubleshooting and knowledge transfer at client sites.</p><hr><div class="tip custom-block"><p class="custom-block-title">🧰 Stack</p><p><code>Python</code> · <code>FastAPI</code> · <code>React</code> · <code>vLLM</code> · <code>NVIDIA Triton</code> · <code>CUDA</code> · <code>Docker</code> · <code>Kubernetes</code> · <code>Linux</code> · <code>PostgreSQL</code> · <code>Redis</code> · <code>NGINX</code> · <code>Prometheus</code> · <code>Grafana</code> · <code>Qdrant</code></p></div>',15),s=[a];function i(c,d,l,g,p,u){return n(),t("div",null,s)}const m=e(r,[["render",i]]);export{f as __pageData,m as default};
